def f(g):
    h=len(g); w=len(g[0])
    th=[(i,j) for i in range(h) for j in range(w) if g[i][j]==3]
    r0,r1=min(p for p,_ in th),max(p for p,_ in th)
    c0,c1=min(q for _,q in th),max(q for _,q in th)
    out=[r[:] for r in g]
    ci=(r0+r1)//2; cj=(c0+c1)//2
    for i in range(r0+1,r1):
        for j in range(c0+1,c1):
            out[i][j]=4 if (i+j)%2==(ci+cj)%2 else 2
    return out
